package ads.poo;

import ads.poo.entity.Circulo;
import ads.poo.entity.Forma;
import ads.poo.entity.Forma2D;
import ads.poo.entity.Linha;
import ads.poo.entity.Retangulo;

public class App {
    public static void main(String[] args) {
        Forma linha = new Linha("Preta", new int[] { 2, 3 }, new int[] { 7, 9 });
        Forma2D circulo = new Circulo("Azul", new int[] { 2, 4 }, 3.0);
        Forma2D retangulo = new Retangulo("Vermelha", new int[] { 2, 6 }, new int[] { 4, 8 });

        IO.println(linha.desenhar());
        IO.println(" --- ");
        IO.println(circulo.desenhar());
        IO.println(circulo.calcularArea());
        IO.println(circulo.calcularPerimetro());
        IO.println(" --- ");
        IO.println(retangulo.desenhar());
        IO.println(retangulo.calcularArea());
        IO.println(retangulo.calcularPerimetro());

    }
}
